#[inline(always)]
unsafe fn DecodeSymbol(
    mut bits: uint64_t,
    mut table: *const HuffmanCode,
    mut br: *mut BrotliBitReader,
) -> uint64_t {
    let idx = (bits & 0xffu64) as isize;
    // SAFETY: `table` points to a valid Huffman decoding table and `idx` is the same in-bounds offset used by the original code.
    let entry = unsafe { &*table.offset(idx) };
    let entry_bits = entry.bits as c_uint;

    if entry_bits > HUFFMAN_TABLE_BITS {
        let nbits = entry_bits.wrapping_sub(HUFFMAN_TABLE_BITS) as uint64_t;
        BrotliDropBits(br, HUFFMAN_TABLE_BITS as uint64_t);
        let sub_idx = (entry.value as uint64_t).wrapping_add((bits >> 8) & BitMask(nbits)) as isize;
        // SAFETY: For second-level lookup, `table.offset(idx)` is a valid first-level entry whose `value` encodes a valid subtable base; `sub_idx` matches the original computation.
        let sub_entry = unsafe { &*table.offset(sub_idx) };
        BrotliDropBits(br, sub_entry.bits as uint64_t);
        sub_entry.value as uint64_t
    } else {
        BrotliDropBits(br, entry.bits as uint64_t);
        entry.value as uint64_t
    }
}

